use harbor.signal;

pub fn entries() -> String {
    let signals = signal.sequence();
    var rendered: List<String> = [];
    var i = 0;

    while i < signals.len() {
        let entry = match signals.get(i) {
            Some(item) => match item {
                signal.Signal.Calm => "calm",
                signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
                signal.Signal.Fog(density) => "fog:".concat(other: density),
            },
            None => "",
        };
        rendered.push(item: entry);
        i = i + 1;
    }

    rendered.join(sep: ";")
}

