use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = feed.frames();
    var total = 0;
    var i = 0;

    while i < frames.len() {
        let value = match frames.get(i) {
            Some(frame) => match feed.decode(frame) {
                Ok(value) => value,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }

    feed.emit(io: io, total: total)?;
    return Ok(unit);
}

