use mill.rules;
use mill.stock;

pub fn lines() -> String {
    let planks = stock.inventory();
    var labels: List<String> = [];
    var i = 0;

    while i < planks.len() {
        match planks.get(i) {
            Some(plank) => {
                if rules.keeps(plank) {
                    labels.push(rules.label(plank));
                }
            },
            None => unit,
        };
        i = i + 1;
    }

    labels.join(",")
}

